-- Batch 06: source-scoped astronomical lexicography; review actual final section keys.
-- Directly inspected al-Biruni (Wright 1934) §§138-139,147-148,168,171,178-181,255-257,260-262.
-- Existing astronomical diagrams, normalized tables, source witnesses, formulas and relations are preserved.
PRAGMA foreign_keys=ON;

UPDATE term_article_sections SET heading='Complementary local angles',body='For a body above the observer''s horizon, altitude and zenith distance are complementary angles measured on the same vertical circle. Their sum is ninety degrees. Both refer to the observer''s local sky; the same celestial body can have different altitudes for observers at different geographical positions.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='altitude') AND section_key='geometry';
UPDATE term_article_sections SET heading='Projecting a position to the ecliptic',body='Al-Bīrūnī (§148) defines the degree of a star with latitude by the degree of the ecliptic intersected by its circle of latitude. Two stars can therefore share the same zodiacal longitude and still be separated north and south of the ecliptic. Equality of longitude is not identical to coincidence in the sky.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='celestial-longitude') AND section_key='coordinate-distinction';
UPDATE term_article_sections SET heading='The two tilted reference circles',body='Al-Bīrūnī (§139) describes the ecliptic as the solar circle of the signs, inclined to the equinoctial. The two great circles meet at opposite equinoctial points; half the ecliptic lies north of the equinoctial and half south. Ecliptic latitude and declination therefore measure displacement relative to different planes.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='ecliptic') AND section_key='equator-intersection';
UPDATE term_article_sections SET heading='The crossing points of two great circles',body='The equinoctial is the great circle perpendicular to the axis of the apparent daily rotation (al-Bīrūnī §138). Because the ecliptic is inclined to it, the two cross at opposing equinox points (§139). The circle is a reference for declination and right ascension, not another path travelled by the Sun.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='equinoctial') AND section_key='equinoxes';
UPDATE term_article_sections SET heading='Local zenith versus the Midheaven',body='The zenith is the direction vertically overhead at the observer. The Midheaven is the intersection of the ecliptic with the local meridian used as a chart angle. Although both refer to the observer''s meridian, they generally occupy different positions on the celestial sphere and should not be identified.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='zenith') AND section_key='geometry';
UPDATE term_article_sections SET heading='Declination and ecliptic latitude',body='Al-Bīrūnī (§147) measures declination north or south of the equinoctial along a circle passing through the celestial poles. He measures latitude north or south of the ecliptic along a circle through the ecliptic poles. As the two reference circles are inclined, a body may have zero declination and nonzero latitude, or the reverse.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='declination') AND section_key='coordinate-distinction';
UPDATE term_article_sections SET heading='A latitude-dependent rising interval',body='Rising time records the equatorial arc corresponding to the rising of a zodiacal interval at a given terrestrial latitude. Away from the equator the zodiacal signs do not consume equal rising times. A table therefore needs its latitude or clime and its measurement convention; the name of the sign alone does not determine the duration.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='rising-times') AND section_key='latitude';
UPDATE term_article_sections SET heading='Apparent daily motion is not proper zodiacal motion',body='First movement carries the sky from east toward west in the traditional geocentric description, producing rising, meridian passages and setting. Its daily sweep is distinguished from the proper, generally eastward zodiacal motion of the Sun and planets. Al-Bīrūnī makes this contrast explicit when discussing the order of planetary positions and motions (§168).',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='first-movement') AND section_key='daily-sweep';
UPDATE term_article_sections SET heading='Motion relative to the signs',body='Second movement describes the progress of luminaries and planets through zodiacal longitude separately from their daily apparent sweep. Thus a planet may move westward across a local observer''s sky over an evening and nevertheless advance eastward against the zodiac over several days. These two statements use different frames of reference.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='second-movement') AND section_key='contrast';
UPDATE term_article_sections SET heading='The smaller circle and its centre',body='In al-Bīrūnī''s account (§178), the planet travels on the circumference of an epicycle while the centre of that smaller circle is carried by the larger deferent. This explains why the planet''s apparent position cannot be identified with the deferent centre itself. The term belongs to a historical geometrical planetary model.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='epicycle') AND section_key='model-role';
UPDATE term_article_sections SET heading='The carrier of an epicycle',body='Al-Bīrūnī (§179) describes the deferent as the circle traced by the epicycle''s centre. In the model he presents its centre is displaced from the world''s centre. The deferent gives the epicycle centre''s path; the epicycle carries the planet; the equant supplies a separate reference for the rate of that motion (§180).',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='deferent') AND section_key='model-role';
UPDATE term_article_sections SET heading='The point of equal angular progress',body='In al-Bīrūnī''s description (§180), equal intervals of time yield equal angles at the equant, not necessarily at the centre of the eccentric deferent. The equant lies on the line through the world''s and deferent''s centres and is distinct from both. He associates this construction with Venus and the three superior planets; it is not a second orbit traversed by the planet.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='equant') AND section_key='model-role';
UPDATE term_article_sections SET heading='A displaced circle, not a modern ellipse',body='Al-Bīrūnī (§171) explains the Sun''s varying apparent distance by a circular orbit with a centre displaced from the centre of the world. Its most distant and nearest points are called apogee and perigee. This historical circular-eccentric construction should not be silently recast as a modern elliptical orbit.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='eccentric-orbit') AND section_key='model-role';
UPDATE term_article_sections SET heading='Specify which circle has the apogee',body='Al-Bīrūnī (§171) calls the point on the Sun''s eccentric circle farthest from Earth the apogee. He later distinguishes the summit of an epicycle from the apogee of the eccentric or deferent (§181). An apogee therefore needs an identified geometric circle; a formula for one component should not be applied to another without evidence.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='apogee') AND section_key='model-role';
UPDATE term_article_sections SET heading='The near point of a specified circle',body='In al-Bīrūnī''s eccentric solar model (§171), perigee is the point of that circle nearest the world''s centre, opposite its apogee. It belongs to the same model and reference centre. The label should not be transferred without qualification to the nearest position of a planet moving simultaneously on a deferent and epicycle.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='perigee') AND section_key='model-role';
UPDATE term_article_sections SET heading='Why every syzygy is not an eclipse',body='A conjunction or opposition of Sun and Moon is necessary for the corresponding solar or lunar eclipse, but not sufficient. The Moon must also be near a node, so that its ecliptic latitude allows one disk or the Earth''s shadow to intercept the other. Al-Bīrūnī links the lunar eclipse condition explicitly to opposition, latitude and proximity to the lunar nodes (§§255–256).',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='eclipse') AND section_key='node-condition';
UPDATE term_article_sections SET heading='Longitude conjunction versus visual covering',body='A longitude conjunction identifies alignment along the ecliptic, but two bodies can still differ in latitude. Occultation is the stricter observational event in which the nearer object actually covers the farther along the observer''s line of sight. It therefore depends on angular positions in both coordinates and on the observer''s viewpoint.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='occultation') AND section_key='conjunction-distinction';
UPDATE term_article_sections SET heading='Latitude bands and unequal rising times',body='Climes are geographical bands established for astronomical reckoning rather than the modern climatic regions of meteorology. In historical practice they help organize differences in the longest daylight interval and in the rising times of zodiacal signs. The geographic bounds and choice of clime system belong to the particular source.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='clime') AND section_key='use';
UPDATE term_article_sections SET heading='Rising, culmination and setting',body='The semi-diurnal arc is half the diurnal arc, measured along the body''s daily circle above the horizon. It extends from rising to the upper meridian passage, or equivalently from that passage to setting under the symmetric spherical model. Its magnitude depends on the body''s declination and the observer''s latitude.',editorial_notes='Batch 06: verified astronomy/reference-frame clarification; existing schemes preserved.' WHERE term_id=(SELECT id FROM terms WHERE slug='semi-diurnal-arc') AND section_key='relation';

